insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('b0bc196d-486e-45e7-9a2e-5dea737925ae', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$inleiding: metingen aan ademhaling en bloeddruk$$,
   $$biologie-havo-2026-i-vanya-in-actie-context1.png$$,
   $$Vanya studeert aan de Academie voor Lichamelijke Opvoeding. Voor het vak inspanningsfysiologie doet ze samen met haar studiegenoot Rachel metingen aan haar ademhaling en bloeddruk.$$, 'inline'),
  ('0e95e81b-8df1-43d4-8e46-5c9facb38e4e', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$kader: spinningfiets (afbeelding 1) en meetresultaten (tabel 1)$$,
   $$biologie-havo-2026-i-vanya-in-actie-context2.png$$,
   $$Vanya gaat vijf minuten fietsen op een spinningfiets (afbeelding 1). Vóór en direct na deze inspanning doet Rachel de volgende metingen bij Vanya:
− ademvolume
− ademhalingsfrequentie
− bloeddruk
De resultaten staan in tabel 1.
afbeelding 1: foto van Vanya op een spinningfiets terwijl Rachel haar bloeddruk meet
tabel 1: ademvolume (L) / ademhalingsfrequentie (per minuut) / bloeddruk bovendruk (mm Hg)
vóór het fietsen: 0,5 / 12 / 115
direct na het fietsen: 3,0 / 24 / 140$$, 'inline'),
  ('d778fe7f-e24e-4160-b05c-ce1a64534ae6', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$verwerking tot een respirogram$$,
   $$biologie-havo-2026-i-vanya-in-actie-context3.png$$,
   $$De meetresultaten van Vanya’s ademvolume en ademhalingsfrequentie worden verwerkt tot een respirogram. Afbeelding 2 toont het respirogram van haar ademhaling vóór het fietsen.$$, 'inline'),
  ('dba11aa8-7b69-4e63-9ff3-c002a626ba47', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$afbeelding 2: respirogram vóór het fietsen$$,
   $$biologie-havo-2026-i-vanya-in-actie-context4.png$$,
   $$afbeelding 2: respirogram (longvolume in liter tegen tijd in seconden, 0-20 s) vóór het fietsen: het longvolume schommelt tussen 2,5 en 3 liter, met 4 ademhalingen in 20 seconden
Vanya gaat tijdens de inspanning vaker en dieper ademhalen. Dit is af te leiden uit de gegevens in tabel 1.$$, 'inline'),
  ('03655903-3d2e-482b-bddd-d6e6f5bef5ca', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$drie uitspraken over diepe en ondiepe ademhaling$$,
   $$biologie-havo-2026-i-vanya-in-actie-context5.png$$,
   $$Vanya en Rachel vergelijken diepe ademhaling met ondiepe ademhaling. Hieronder staan uitspraken over deze vergelijking.
1 Tijdens een diepe uitademing trekken de buikspieren sterker samen.
2 Bij diepe ademhaling is de dode ruimte groter.
3 Bij een diepe uitademing is het restvolume kleiner.$$, 'inline'),
  ('11d24dd6-2f3a-455a-915e-c14ba9aab88a', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$bloedverdeling en het autonome zenuwstelsel$$,
   $$biologie-havo-2026-i-vanya-in-actie-context6.png$$,
   $$De bloedverdeling in Vanya’s lichaam wordt door het autonome zenuwstelsel aangepast aan haar activiteit.$$, 'inline'),
  ('0ea70af4-abb2-4dfc-8c69-e78ee38b66fa', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$bloeddruk en slagvolume$$,
   $$biologie-havo-2026-i-vanya-in-actie-context7.png$$,
   $$Tijdens de inspanning neemt Vanya’s bloeddruk geleidelijk toe. Dit komt onder andere doordat het slagvolume van haar hart toeneemt.$$, 'inline'),
  ('6d611a0c-8438-46f4-b041-43178c2df4bf', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$kader: tweede inspanning, verzuring van de beenspieren$$,
   $$biologie-havo-2026-i-vanya-in-actie-context8.png$$,
   $$Een kwartier na afloop van de inspanning doen Vanya en Rachel het onderzoek nog een keer. Daarbij fietst Vanya zo hard als ze kan. Ruim voordat de vijf minuten voorbij zijn, moet ze stoppen omdat haar beenspieren verzuren.$$, 'inline'),
  ('206f3076-4103-4fb1-80ce-5ee98e5e518f', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$pH-daling door melkzuur$$,
   $$biologie-havo-2026-i-vanya-in-actie-context9.png$$,
   $$De pH in Vanya’s spierweefsel is gedaald door de ophoping van melkzuur.$$, 'inline'),
  ('26e62800-c9f7-4d94-8b90-d40570599ed7', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', $$kader: na de tweede inspanning neemt melkzuur af$$,
   $$biologie-havo-2026-i-vanya-in-actie-context10.png$$,
   $$Na de tweede inspanning dalen Vanya’s ademvolume en bloeddruk weer naar het niveau van vóór de inspanning. Ook de concentratie melkzuur in haar spierweefsel neemt af.$$, 'inline'),
  ('437eab18-bd2a-4e57-8689-da2a6dff1eb9', '433c7164-94ac-404f-8d11-7c55f030edce', $$inleiding: de beekprik is bedreigd door slechte waterkwaliteit$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context1.png$$,
   $$De beekprik is in Nederland een bedreigde diersoort. Een van de oorzaken is dat de waterkwaliteit in veel beken niet goed genoeg is.$$, 'inline'),
  ('959a7afe-fe99-4db7-94d3-5bde92be5908', '433c7164-94ac-404f-8d11-7c55f030edce', $$kader: de beekprik (afbeelding 1) en zijn leefgebied in de beek$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context2.png$$,
   $$De beekprik (Lampetra planeri, afbeelding 1) is een vis die ongeveer 15 centimeter lang wordt.
afbeelding 1: foto van een beekprik
Beekprikken komen in Nederland nog maar in enkele beken voor. Deze beken ontspringen in hoger gelegen moerasbossen. Het water is daar voedselarm en de beekbodem bestaat uit zand en grind. Stroomafwaarts slingert de beek door loofbos en landbouwgrond en neemt de concentratie van anorganische stoffen toe. Hier groeien op de beekbodem enkele waterplanten. Nog verder stroomafwaarts liggen organische resten op de bodem.$$, 'inline'),
  ('5a959dc5-9422-42b9-906b-c399cc43367d', '433c7164-94ac-404f-8d11-7c55f030edce', $$stroomafwaarts steeds voedselrijker water$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context3.png$$,
   $$Vanaf de bron van de beek wordt het water stroomafwaarts steeds voedselrijker: de concentratie van anorganische stoffen neemt toe.$$, 'inline'),
  ('e3b40bfe-90a6-45d5-aa40-89624ef204d3', '433c7164-94ac-404f-8d11-7c55f030edce', $$schaduw door bomen langs de beek$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context4.png$$,
   $$Bomen langs de beek zorgen voor schaduw.$$, 'inline'),
  ('de402494-2d7e-49c2-89bf-31daa307b4e0', '433c7164-94ac-404f-8d11-7c55f030edce', $$kader: voortplanting en voedsel van beekprikken en beekpriklarven$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context5.png$$,
   $$Volwassen beekprikken zwemmen stroomopwaarts om eitjes af te zetten op de grindrijke beekbodem. Zodra de beekpriklarven uit de eitjes komen, laten ze zich met de stroom meevoeren naar plekken waar de bodem van de beek bestaat uit zand en slib. De beekpriklarven eten algen en kleine meercellige waterorganismen, zoals raderdiertjes. Raderdiertjes leven van algen en van eencellige organismen zoals trilhaardiertjes, amoeben en sporendiertjes. Deze eencellige organismen voeden zich onder andere met algen.$$, 'inline'),
  ('0954292d-1640-4910-beea-5af9f5bdec85', '433c7164-94ac-404f-8d11-7c55f030edce', $$langgerekt, cilindervormig lichaam$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context6.png$$,
   $$De beekprik heeft een langgerekt, cilindervormig lichaam (afbeelding 1).$$, 'inline'),
  ('af7b7d70-4ad2-4177-ab5a-01674ffcda6f', '433c7164-94ac-404f-8d11-7c55f030edce', $$voedselweb in het kader boven vraag 9$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context7.png$$,
   $$In de tekst in het kader boven vraag 9 is een voedselweb beschreven.$$, 'inline'),
  ('4e1bee9e-fe4e-4925-9822-51c4d9db0915', '433c7164-94ac-404f-8d11-7c55f030edce', $$metamorfose van larve tot volwassen vis$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context8.png$$,
   $$Tijdens de metamorfose van larve tot volwassen vis ontwikkelen de beekpriklarven ogen, vinnen en geslachtsorganen. Tijdens deze ontwikkeling verdwijnt het darmkanaal; volwassen beekprikken eten dus niet. Ze zwemmen stroomopwaarts, waar ze zich voortplanten en daarna sterven.$$, 'inline'),
  ('39f4a82b-35ee-4770-8b56-bc594f410d72', '433c7164-94ac-404f-8d11-7c55f030edce', $$kader: experiment tolerantiegrenzen voor zuurstof (afbeelding 2)$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context9.png$$,
   $$Als er in de zomer weinig regen valt, neemt de stroomsnelheid van het water in de beken af. Daardoor daalt de zuurstofconcentratie in het water. Volwassen beekprikken kunnen alleen leven in zuurstofrijk water. Beekpriklarven zijn minder gevoelig voor een lage zuurstofconcentratie in het water dan volwassen beekprikken.
Wetenschappers deden een experimenteel onderzoek naar de tolerantiegrenzen van beekpriklarven voor zuurstof bij verschillende temperaturen. Ze plaatsten beekpriklarven in twee bakken met een verschillende watertemperatuur. In elke bak waren vijf beekpriklarven aanwezig.
Tijdens het experiment werd na twee, na vier en na zes dagen de zuurstofconcentratie in het water (uitgedrukt in de zuurstofverzadiging) verlaagd. Twee keer per dag werd de sterfte van de beekpriklarven bepaald. In afbeelding 2 zie je de resultaten.
afbeelding 2: twee diagrammen (10 °C en 20 °C) met tegen de tijd (0-10 dagen) de zuurstofverzadiging (%, lijn) en de sterfte van beekpriklarven (%, grijs vlak); bij beide temperaturen daalt de zuurstofverzadiging stapsgewijs: 20% tot dag 2, 15% vanaf ongeveer dag 2,5, 10% vanaf ongeveer dag 4,5 en ongeveer 5% vanaf ongeveer dag 6,5
10 °C: sterfte 0% tot dag 3, 20% van dag 3 tot 7, 40% van dag 7 tot 9, 100% vanaf dag 9
20 °C: sterfte 0% tot dag 4, 20% van dag 4 tot 4,5, 40% van dag 4,5 tot 6, 60% van dag 6 tot 7, 80% van dag 7 tot 9, 100% vanaf dag 9$$, 'inline'),
  ('6533b1b6-c419-485e-8d07-dc581b701101', '433c7164-94ac-404f-8d11-7c55f030edce', $$drie uitspraken over de resultaten$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context10.png$$,
   $$Hieronder staan uitspraken over de resultaten van dit experiment.
1 Na 3 dagen bij een temperatuur van 20 °C was de sterfte van de beekpriklarven ongeveer 15%.
2 Uit afbeelding 2 blijkt dat de maximum-tolerantiegrens van beekpriklarven voor temperatuur 10 °C is.
3 Het moment waarop meer dan de helft van de beekpriklarven is doodgegaan, was bij 20 °C eerder dan bij 10 °C.$$, 'inline'),
  ('f66513f8-69d9-48cf-b7af-509e22b356a6', '433c7164-94ac-404f-8d11-7c55f030edce', $$tolerantiegrenzen voor zuurstof van volwassen beekprikken$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context11.png$$,
   $$Voor volwassen beekprikken zijn de tolerantiegrenzen voor zuurstof anders dan voor beekpriklarven. In afbeelding 3 staat een grafiek van de relatie tussen zuurstofconcentratie in het water en de overleving van beekpriklarven.$$, 'inline'),
  ('2d528127-fdc2-407a-b534-b346bffe6658', '433c7164-94ac-404f-8d11-7c55f030edce', $$afbeelding 3: overleving van beekpriklarven en zuurstofconcentratie$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context12.png$$,
   $$afbeelding 3: grafiek van de overleving (%) tegen de zuurstofconcentratie; de stippellijn van de beekpriklarven stijgt S-vormig van 0 naar 100%$$, 'inline'),
  ('2c85388b-330e-49f3-acb2-57c2614355fc', '433c7164-94ac-404f-8d11-7c55f030edce', $$barrières en vispassages$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context13.png$$,
   $$Een andere bedreiging voor de beekprik zijn barrières, zoals watermolens. Deze maken de beek stroomopwaarts onbereikbaar voor volwassen beekprikken. Waterschappen proberen barrières op te heffen door vispassages aan te leggen (afbeelding 4).$$, 'inline'),
  ('1286a436-d533-4eda-a71d-9efcb7b112e9', '433c7164-94ac-404f-8d11-7c55f030edce', $$afbeelding 4: vispassage bij een watermolen$$,
   $$biologie-havo-2026-i-bedreigingen-voor-de-beekprik-context14.png$$,
   $$afbeelding 4: kaartje van een beek met een molen en een vispassage die om de molen heen loopt (met de stroomrichting), en een foto van de situatie
Legenda:
1 stuw
2 molenrad
3 uitstroom vispassage$$, 'inline'),
  ('a7dc70a7-e1e2-40d9-825d-0b585be831c3', '401b6056-497b-458b-b797-8dd49df437a5', $$inleiding: stroperij en razendsnelle verandering$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context1.png$$,
   $$Aan het eind van de vorige eeuw doodden stropers veel Afrikaanse olifanten om hun ivoren slagtanden. Als gevolg van deze stroperij blijkt de soort razendsnel veranderd te zijn. Bioloog Shane Campbell-Staton deed hier onderzoek naar.$$, 'inline'),
  ('9e7066f1-bf82-41f9-9167-b8b2470a1142', '401b6056-497b-458b-b797-8dd49df437a5', $$kader: populatie olifanten in Gorongosa in 1977 en 2000$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context2.png$$,
   $$In 1977 bestond de populatie olifanten (Loxodonta africana) in het Nationaal Park Gorongosa in Mozambique uit 1271 vrouwtjes. Hiervan had 18,5% geen slagtanden (slagtandloos). Op de foto hiernaast zie je zo’n slagtandloos vrouwtje.
In 2000 waren er nog maar 121 vrouwtjes, waarvan er 61 slagtandloos waren. Alle mannetjes in de populatie hadden wél slagtanden.
foto van een slagtandloos olifantenvrouwtje$$, 'inline'),
  ('8b81c0c3-d1ae-4437-b021-e25f410ce765', '401b6056-497b-458b-b797-8dd49df437a5', $$absoluut afgenomen, relatief toegenomen$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context3.png$$,
   $$In de periode 1977 tot en met 2000 is het aantal slagtandloze vrouwtjes absoluut gezien afgenomen, maar relatief gezien toegenomen.$$, 'inline'),
  ('cb81a79d-b972-4ece-a2ee-e5fbf3c01cea', '401b6056-497b-458b-b797-8dd49df437a5', $$beschrijving van het onderzoek$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context4.png$$,
   $$Hieronder staat een beschrijving van het onderzoek van Campbell-Staton.$$, 'inline'),
  ('1b5bac7e-ec98-4cca-92d5-ff248cdbcfa3', '401b6056-497b-458b-b797-8dd49df437a5', $$kader: onderzoek van Campbell-Staton (regels 1-6)$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context5.png$$,
   $$1 Campbell-Staton vroeg zich af wat de oorzaak was van de relatieve
2 toename van het aantal slagtandloze vrouwtjes. Het zou een toevallig
3 gevolg kunnen zijn van de afname van de populatie. Het zou echter ook
4 een gevolg kunnen zijn van evolutie. Met kansberekening toonde hij aan
5 dat er sprake was van selectievoordeel van een bepaalde erfelijke
6 eigenschap.$$, 'inline'),
  ('0cf199e3-beca-4dec-8625-6322c3644a35', '401b6056-497b-458b-b797-8dd49df437a5', $$kader: X-chromosomale mutatie, dominant allel$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context6.png$$,
   $$De afwezigheid van slagtanden wordt veroorzaakt door een mutatie van een gen dat op het X-chromosoom ligt. Het allel ‘afwezigheid van slagtanden’ is hierbij dominant over het allel voor slagtanden.$$, 'inline'),
  ('96134395-8084-4efa-9c41-2a9535587431', '401b6056-497b-458b-b797-8dd49df437a5', $$heterozygoot vrouwtje × mannetje met slagtanden$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context7.png$$,
   $$Een olifantenvrouwtje dat voor deze eigenschap heterozygoot is, paart met een mannetje met slagtanden. Ze raakt in verwachting van een dochter.$$, 'inline'),
  ('8e167837-d1a2-44cb-bdea-352037cf4a7c', '401b6056-497b-458b-b797-8dd49df437a5', $$allel letaal bij mannetjes$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context8.png$$,
   $$Campbell-Staton zag iets opvallends. Bij heterozygote slagtandloze vrouwtjes was er een ongewone verhouding tussen hun vrouwelijke en mannelijke nakomelingen. Hieruit trok hij de conclusie dat het allel ‘afwezigheid van slagtanden’ bij mannetjes letaal is.$$, 'inline'),
  ('4b377070-2558-430b-83cf-c6b26e74c8f9', '401b6056-497b-458b-b797-8dd49df437a5', $$kleinere genenpool door stroperij$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context9.png$$,
   $$Stroperij kan in korte tijd grote gevolgen hebben, doordat de populatiegrootte sterk afneemt. Het maakt de olifantenpopulatie kwetsbaarder voor uitsterven doordat de genenpool kleiner wordt.$$, 'inline'),
  ('0f7222a6-f314-4c0f-9731-4ec0f028c035', '401b6056-497b-458b-b797-8dd49df437a5', $$olifanten rukken struiken uit de grond$$,
   $$biologie-havo-2026-i-razendsnelle-adaptatie-bij-olifanten-door-stroperij-context10.png$$,
   $$Olifanten hebben een groot effect op het ecosysteem waarin ze leven. Met hun slagtanden rukken ze struiken uit de grond als ze door een dichtbegroeid bos lopen. Hierdoor kan de rijkdom aan soorten in het gebied toenemen. Bij slagtandloze olifanten zou dit effect op de biodiversiteit kleiner kunnen zijn.$$, 'inline'),
  ('76c6ad23-af2b-4f20-8075-5a36395af07a', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$inleiding: plantenveredeling voor de biologische landbouw$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context1.png$$,
   $$Onderzoeker Guusje Bonnema van Wageningen University & Research veredelt planten voor de biologische landbouw. Zij kweekt plantenrassen die beter samenwerken met de organismen in de bodem, en beter bestand zijn tegen ziekteverwekkers.$$, 'inline'),
  ('362a20be-e871-4c44-85df-3f4c012318a3', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$kader: vruchtwisseling en strokenteelt (foto)$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context2.png$$,
   $$Boeren met een biologisch landbouwbedrijf gebruiken geen kunstmest en ook geen chemische bestrijdingsmiddelen. Ze zaaien elk jaar een ander gewas op hun akker, zodat de bodem vruchtbaar blijft en het aantal ziekteverwekkers laag blijft. Dit heet vruchtwisseling.
Ook telen ze vaak meerdere gewassen op dezelfde akker in strokenteelt. Zie de foto hieronder.
foto van een akker met gewassen in stroken$$, 'inline'),
  ('08b0379e-18bf-4c7e-8f94-d9173fc67cec', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$zonder kunstmest neemt de hoeveelheid mineralen af$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context3.png$$,
   $$Sommige experts beweren dat met biologische landbouw nooit de hele wereldbevolking gevoed kan worden. Hun argument is dat zonder het gebruik van kunstmest de hoeveelheid mineralen in de bodem afneemt.$$, 'inline'),
  ('58d7f459-bcc0-4753-93c7-b7fece92e1f6', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$monocultuur en strokenteelt; twee uitspraken$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context4.png$$,
   $$Bij monocultuur verbouwt een boer één gewas tegelijk op een groot stuk land. Bij strokenteelt verbouwt een boer twee of meer gewassen in stroken van een aantal meter breed. Hieronder staan uitspraken over de vergelijking tussen monocultuur en strokenteelt.
1 Bij monocultuur is de kans op plagen groter.
2 Bij strokenteelt is de diversiteit aan dierlijke organismen groter.$$, 'inline'),
  ('640e6b9b-2ea5-4b16-97e8-88f5231db98c', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$onderzoeksvraag over vruchtwisseling en ziekteverwekkers$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context5.png$$,
   $$Onderzoekers hebben de volgende onderzoeksvraag: Is in de bodem van akkers waarop vruchtwisseling wordt toegepast, het aantal ziekteverwekkende bodemorganismen lager dan in de bodem van akkers waarop elk jaar hetzelfde gewas wordt geteeld?$$, 'inline'),
  ('9c0a2771-0918-47f4-90a0-5ee9f7de9fd4', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$erwten in symbiose met knolletjesbacteriën$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context6.png$$,
   $$Sommige biologische boeren zaaien erwten samen in met andere gewassen. De erwtenplanten (vlinderbloemige planten) leven in symbiose met knolletjesbacteriën. Door deze symbiose hoeft de boer minder mest aan te brengen op de akkers.$$, 'inline'),
  ('ef2772bc-bdf9-409e-85cd-8ad756da8ec3', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$mycorrhiza: symbiose van schimmels en plantenwortels$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context7.png$$,
   $$Bonnema stelt dat sommige plantenrassen beter samenwerken met bodemorganismen dan andere plantenrassen. Bij deze samenwerking speelt mycorrhiza, een symbiose tussen schimmels en plantenwortels, een belangrijke rol. De schimmels bevorderen de opname van mineralen door planten. In ruil daarvoor krijgt de schimmel voedingsstoffen van de plant.$$, 'inline'),
  ('b50a7234-53f9-4c8d-9265-7263fd9d112c', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$kader: effectoren, receptoren en resistentiegenen$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context8.png$$,
   $$Bonnema doet onderzoek aan planten die van nature resistent zijn tegen ziekteverwekkers. Sommige ziekteverwekkers maken gebruik van bepaalde stoffen (effectoren) om planten te infecteren. Deze effectoren onderdrukken de natuurlijke afweer van de plant. Er zijn planten die de effectoren kunnen herkennen met behulp van receptoren in het cytoplasma van hun cellen. Als een effector bindt aan zo’n receptor, leidt dit tot sterfte van de cel. Daardoor sterft ook de ziekteverwekker. Specifieke resistentiegenen coderen voor deze receptoren. Planten met de juiste resistentiegenen zijn daardoor resistent tegen bepaalde ziekteverwekkers.$$, 'inline'),
  ('ab261761-d872-433f-8a1c-6d12f924cbff', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$schematische tekening van een geïnfecteerde plantencel$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context9.png$$,
   $$In de onderstaande afbeelding zie je een schematische tekening van een plantencel die is geïnfecteerd door een ziekteverwekker.$$, 'inline'),
  ('98a8fa73-3d2d-4fef-a387-051778330872', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$afbeelding: plantencel met ziekteverwekker en letters P, Q, R en S$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context10.png$$,
   $$afbeelding: schematische tekening van een plantencel met een ziekteverwekker erin; in de kern een dubbele streng (P) waarvan een enkele streng (Q) wordt gemaakt; deze streng gaat naar het cytoplasma, waar langs de streng een keten van bolletjes wordt gevormd; die keten wordt een gevouwen molecuul (R); verspreid in de cel liggen kleine driehoekjes (S)$$, 'inline'),
  ('872484e9-90a5-47b3-a225-404c903ac155', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$moleculen bij de interactie tussen plantencel en ziekteverwekker$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context11.png$$,
   $$Hieronder staan moleculen die betrokken zijn bij de interactie tussen plantencel en ziekteverwekker.
− DNA
− effector
− receptor
− RNA$$, 'inline'),
  ('a816bd75-0047-44d4-a790-02bcf7933c6c', '616e5649-7b25-4ff9-b24b-faa9404b3cee', $$mutatie bij de ziekteverwekker$$,
   $$biologie-havo-2026-i-plantenveredeling-voor-biologische-landbouw-context12.png$$,
   $$Soms ontstaat er bij de ziekteverwekker een mutatie waardoor de ziekteverwekker een resistente plant wél weer kan infecteren.$$, 'inline'),
  ('22c053e9-4248-4f1c-a040-496752e0ab05', '00de4a99-8c85-4f89-a195-85e198cacc18', $$inleiding: Sjoerd krijgt een gastric bypass$$,
   $$biologie-havo-2026-i-gastric-bypass-context1.png$$,
   $$Sjoerd heeft zeer ernstig overgewicht. Ondanks intensieve begeleiding is het hem niet gelukt om af te vallen. Hij is daarom nu onder behandeling bij een specialist in het ziekenhuis. Sjoerd krijgt een operatieve maagverkleining: een gastric bypass.$$, 'inline'),
  ('cda93a5d-2019-4b23-99a6-3ad6dc9a730a', '00de4a99-8c85-4f89-a195-85e198cacc18', $$kader: de operatie (afbeelding 1)$$,
   $$biologie-havo-2026-i-gastric-bypass-context2.png$$,
   $$Bij een gastric bypass (afbeelding 1) snijdt de chirurg het bovenste deel van de maag los, zodat daar een kleine maag (de pouch) ontstaat. Hij maakt de rest van de maag aan de bovenkant weer dicht. Daarna snijdt hij de dunne darm door, vlak boven P. Het uiteinde P verbindt hij met de pouch. Het andere uiteinde (Q) verbindt hij anderhalve meter na de uitgang van de pouch aan de dunne darm.
afbeelding 1: drie tekeningen: maag en dunne darm vóór de operatie (slokdarm, maag, dunne darm, P); de losgesneden pouch en de doorgesneden dunne darm (P en Q); de situatie na de operatie, waarbij P op de pouch is aangesloten, Q verderop op de dunne darm, en R het deel van de dunne darm na de aansluiting van Q
Na deze operatie produceren het onderste deel van de maag, de lever en de alvleesklier nog steeds spijsverteringssappen. Deze komen op een andere plek met de voedselbrij in contact dan vóór de operatie. De pouch produceert geen spijsverteringssap.$$, 'inline'),
  ('8aa90a82-663d-4f14-a413-ceca2f03dc64', '00de4a99-8c85-4f89-a195-85e198cacc18', $$tabel: koolhydraat- en eiwitvertering in de pouch en op plaats R$$,
   $$biologie-havo-2026-i-gastric-bypass-context3.png$$,
   $$De pouch en plaats R uit afbeelding 1 staan ook in de volgende tabel.
tabel: plaats / koolhydraatvertering / eiwitvertering
in de pouch: (leeg) / (leeg)
op plaats R: (leeg) / (leeg)$$, 'inline'),
  ('d2d2c97b-2b28-4930-849d-0b77ba8661a2', '00de4a99-8c85-4f89-a195-85e198cacc18', $$verminderde resorptie na de darmverkorting$$,
   $$biologie-havo-2026-i-gastric-bypass-context4.png$$,
   $$De arts vertelt Sjoerd dat hij na de operatie zal gaan afvallen. Met een kleine maag kan hij minder grote porties eten. Door de verkorting van de darm zullen er minder voedingsstoffen geresorbeerd worden. Er komen dan relatief meer vetten in de ontlasting terecht.$$, 'inline'),
  ('2a42d3a7-cf24-47a5-9c95-a7e2ccf480c1', '00de4a99-8c85-4f89-a195-85e198cacc18', $$kader: gastrine stimuleert de afgifte van maagzuur$$,
   $$biologie-havo-2026-i-gastric-bypass-context5.png$$,
   $$Normaal stimuleert het hormoon gastrine de afgifte van maagzuur. Gastrine wordt in het onderste deel van de maag gemaakt als er eiwitten aanwezig zijn in de maag. De aangemaakte gastrine wordt afgegeven aan het bloed.$$, 'inline'),
  ('ac600a73-f07b-4d09-8b7b-6d01d2f07959', '00de4a99-8c85-4f89-a195-85e198cacc18', $$dumpingsyndroom$$,
   $$biologie-havo-2026-i-gastric-bypass-context6.png$$,
   $$Na de operatie zal Sjoerd begeleiding krijgen van een diëtist. Een van de dingen waar hij op moet gaan letten, is zijn eetpatroon. Hij moet verspreid over de dag kleine porties gaan eten. Als hij toch te grote porties eet, kan hij zich plotseling onwel gaan voelen. Dat heet het dumpingsyndroom. Dumpingsyndroom ontstaat als eten in te grote, droge brokken in de dunne darm terechtkomt. In de dunne darm wordt dan veel water aan het bloed onttrokken, zodat de voedselbrij smeuïger wordt. Dit vindt binnen een uur na de maaltijd plaats.$$, 'inline'),
  ('ccf08cf4-b93b-4d53-8282-cd0a33114453', '492be042-7f0b-4c0e-8ee4-e2194a802a24', $$inleiding: vier soorten giraffen op basis van DNA-onderzoek$$,
   $$biologie-havo-2026-i-giraffen-aparte-soorten-context1.png$$,
   $$Volgens Duitse wetenschappers behoren niet alle giraffen tot dezelfde soort, maar zijn er vier verschillende soorten giraffen. Deze conclusie trekken ze op basis van DNA-onderzoek.$$, 'inline'),
  ('befcc21a-df82-47b5-882b-11811e4826e5', '492be042-7f0b-4c0e-8ee4-e2194a802a24', $$kader: ondersoorten en reproductieve isolatie$$,
   $$biologie-havo-2026-i-giraffen-aparte-soorten-context2.png$$,
   $$Lange tijd werden alle giraffen tot dezelfde soort (Giraffa camelopardalis) gerekend. Omdat giraffen in verschillende gebieden duidelijk een verschillend uiterlijk hebben, werd de soort in een aantal ondersoorten ingedeeld. De Duitse wetenschappers analyseerden het DNA van giraffen van de verschillende ondersoorten. Ze leidden daaruit af dat er al zo lang reproductieve isolatie is tussen de verschillende giraffenpopulaties dat het vier aparte soorten zijn geworden.$$, 'inline'),
  ('f91a35d8-e8fc-4590-932b-a59746c1d7c8', '492be042-7f0b-4c0e-8ee4-e2194a802a24', $$coderend en niet-coderend DNA$$,
   $$biologie-havo-2026-i-giraffen-aparte-soorten-context3.png$$,
   $$DNA is in te delen in coderend DNA en niet-coderend DNA.$$, 'inline'),
  ('e0279e6c-d54f-4600-a679-2f7ff34c9fc3', '492be042-7f0b-4c0e-8ee4-e2194a802a24', $$soortbepaling zonder DNA-analyse$$,
   $$biologie-havo-2026-i-giraffen-aparte-soorten-context4.png$$,
   $$Ook zonder DNA-analyse is het mogelijk om vast te stellen of individuen uit verschillende populaties tot verschillende soorten behoren.$$, 'inline'),
  ('ea2dbac9-d3bc-45e3-a7c2-44c9aa467135', '492be042-7f0b-4c0e-8ee4-e2194a802a24', $$kader: kaart met leefgebieden en verwantschap van de vier soorten$$,
   $$biologie-havo-2026-i-giraffen-aparte-soorten-context5.png$$,
   $$Op de kaart hiernaast zie je een deel van Afrika met daarin de leefgebieden van de vier soorten giraffen.
De wetenschappers vonden de minste verschillen in DNA tussen de noordelijke giraf (Nog) en de netgiraf (Neg).
De masaigiraf (Mag) is meer verwant aan de zuidelijke giraf (Zug) dan aan de andere twee giraffensoorten.
kaart van een deel van Afrika met de leefgebieden van Nog, Neg, Mag en Zug$$, 'inline'),
  ('c844123a-692d-4509-89d4-fcaf6442844b', '492be042-7f0b-4c0e-8ee4-e2194a802a24', $$evolutionaire stamboom van de giraf-achtigen$$,
   $$biologie-havo-2026-i-giraffen-aparte-soorten-context6.png$$,
   $$In de evolutionaire stamboom zie je de giraf en enkele verwante soorten afgebeeld.
stamboom met Sivatherium, okapi, Samotherium, giraf, Canthumeryx en Prodremotherium, met een tijdas van 20 miljoen jaar geleden tot nu (0)
Met de DNA-gegevens pasten de wetenschappers deze evolutionaire stamboom van de giraf-achtigen aan.$$, 'inline'),
  ('362ca7eb-4a4a-41fa-9d6c-c84440286007', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$inleiding: mastitis bestrijden met antistoffen$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context1.png$$,
   $$Van alle antibiotica die worden gebruikt bij melkkoeien, dient meer dan de helft om uierontsteking (mastitis) te bestrijden. Het bedrijf Mastivax bv doet onderzoek naar de bestrijding van mastitis met behulp van antistoffen. Op deze manier zou het antibioticagebruik verminderd kunnen worden.$$, 'inline'),
  ('9498f776-9727-4950-9db9-5e68f8154ec1', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$kader: oxytocine en melkafgifte (afbeelding uier en melkklieren)$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context2.png$$,
   $$Een koe gaat pas melk geven als ze een kalf heeft gekregen. Als de koe daarna twee keer per dag wordt gemolken, blijft ze melk produceren. Als een kalf of een melkmachine aan een tepel van de uier zuigt, komt oxytocine vrij uit de hypofyse van de koe. Deze stof stimuleert de melkafgifte vanuit de melkklieren. Dit zie je in de volgende afbeelding.
afbeelding: foto van een uier met een doorsnede (melkklier, tepelholte, tepelkanaal) en een vergroting van een melkklier (melk, melkkanaaltje, bloedvat, spiercel rond melkklier); na stimulering door oxytocine wordt de melk uit de melkklier geperst$$, 'inline'),
  ('6020fe38-75cb-4663-ba5a-a9905b429a5b', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$drie uitspraken over de melkafgifte$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context3.png$$,
   $$Hieronder staan uitspraken over de melkafgifte.
1 Bij de processen die leiden tot de melkafgifte na het zuigen aan de tepel, zijn het zenuwstelsel en het hormoonstelsel van de koe betrokken.
2 Oxytocine laat de spiercellen rondom de melkklieren ontspannen.
3 Melkklieren zijn exocriene klieren.$$, 'inline'),
  ('65ca37db-3ecc-46f1-941c-76611b5fd50d', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$vier barrières in de uier$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context4.png$$,
   $$De uier van een koe heeft barrières die de kans op mastitis verminderen. Hieronder staan vier processen.
1 Een kringspier rond het tepelkanaal spant na het melken aan.
2 Cellen van het tepelkanaal produceren vetzuren die de pH laten dalen.
3 Melkkliercellen produceren het eiwit lactoferrine, dat ijzer bindt, zodat ijzer niet beschikbaar is voor bacteriën.
4 Het tepelkanaal kan tijdelijk afgesloten worden door een eiwit-prop.$$, 'inline'),
  ('753323db-5763-4e70-a5ac-daa2bef4549a', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$kader: mastitis en ontstekingsreactie$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context5.png$$,
   $$Research-analist Janine Donker werkt mee aan het onderzoek. Ze spoort koeien op die mastitis hebben. Bij mastitis zijn de melkklieren in de uier ontstoken door een infectie met bacteriën. Als de bacteriën niet voldoende worden opgeruimd door macrofagen, treedt een ontstekingsreactie op.$$, 'inline'),
  ('552522eb-d4bd-4550-8901-2c462b90cf58', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$mediatoren bij de ontstekingsreactie$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context6.png$$,
   $$Bij de ontstekingsreactie geven afweercellen stoffen (mediatoren) af. De uier wordt dan rood, en door vochtophoping zwelt het uierweefsel op. Dit is vergelijkbaar met processen die optreden tijdens een allergische reactie.$$, 'inline'),
  ('9b66a60b-2fae-483c-80e0-43212d3bbaed', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$kader: antistoffen uit melk toegediend in de uier (foto)$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context7.png$$,
   $$In melk van koeien met mastitis zijn antistoffen in een lage concentratie aanwezig. Mastivax isoleert deze antistoffen uit ingezamelde melk. Normaal krijgen koeien met mastitis antibiotica toegediend in de uier. Bij de koeien in het onderzoek dient Donker in plaats daarvan de antistoffen toe in de uier.
foto van het toedienen in de uier$$, 'inline'),
  ('270c799f-805c-4dbc-8861-009b27ca473a', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$antistoffen geproduceerd door het afweersysteem van koeien$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context8.png$$,
   $$De antistoffen zijn geproduceerd door het afweersysteem van koeien.$$, 'inline'),
  ('fb0aa46d-dc21-4da6-9ee0-7df914a0dac6', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$antistoffen helpen macrofagen$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context9.png$$,
   $$De toegediende antistoffen maken het voor macrofagen in de uier makkelijker om de bacteriën te vernietigen.$$, 'inline'),
  ('41711316-109b-42cc-a283-aaaa95c5a73c', '1abae8a9-83a5-42d6-aa3d-4bc6bc835374', $$minder gebruik van antibiotica$$,
   $$biologie-havo-2026-i-mastitis-bestrijden-zonder-antibiotica-context10.png$$,
   $$Door antistoffen te gebruiken in de behandeling van mastitis, kan het gebruik van antibiotica worden teruggedrongen.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('186f44b5-8a95-4b9b-8598-97c1b069f825', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', 1,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["respirogram", "ademvolume", "ademhalingsfrequentie", "longventilatie", "grafiek interpreteren"]'::jsonb,
   $$Kiezen van het respirogram dat past bij een groter ademvolume en een hogere ademhalingsfrequentie na inspanning.$$,
   $$biologie-havo-2026-i-vanya-in-actie-vraag1.png$$, $$2p 1 Welk van de onderstaande respirogrammen is een juiste weergave van haar ademhaling direct na het fietsen?
A, B, C, D: vier respirogrammen (longvolume in liter tegen tijd 0-20 seconden); A en B schommelen tussen ongeveer 1,5 en 4,5 liter, C en D tussen 0 en 3 liter; A en C tonen meer ademhalingen in 20 seconden dan B en D$$, array['b0bc196d-486e-45e7-9a2e-5dea737925ae', '0e95e81b-8df1-43d4-8e46-5c9facb38e4e', 'd778fe7f-e24e-4160-b05c-ce1a64534ae6', 'dba11aa8-7b69-4e63-9ff3-c002a626ba47']::uuid[]),
  ('bbb9a09e-c188-4312-919b-a572c3d6ec06', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', 2,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["ademhaling", "uitademing", "buikspieren", "dode ruimte", "restvolume"]'::jsonb,
   $$Beoordelen van uitspraken over ademhalingsspieren, dode ruimte en restvolume bij diepe ademhaling.$$,
   $$biologie-havo-2026-i-vanya-in-actie-vraag2.png$$, $$2p 2 Schrijf de nummers 1, 2 en 3 onder elkaar. Noteer erachter of de bijbehorende uitspraak juist of onjuist is.$$, array['03655903-3d2e-482b-bddd-d6e6f5bef5ca']::uuid[]),
  ('a82a0313-758f-4839-a2bd-a81b13edbef0', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', 3,
   '[{"domain": "Zelfregulatie", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
   '["autonoom zenuwstelsel", "orthosympathisch zenuwstelsel", "parasympathisch zenuwstelsel", "doorbloeding", "inspanning"]'::jsonb,
   $$Herkennen dat het orthosympathisch zenuwstelsel bij inspanning actief is en de doorbloeding van de darmen vermindert.$$,
   $$biologie-havo-2026-i-vanya-in-actie-vraag3.png$$, $$2p 3 Welk deel van haar autonome zenuwstelsel is het meest actief tijdens het fietsen? En wat is het effect hiervan op de doorbloeding van haar darmen?
meest actief tijdens fietsen doorbloeding darmen
A orthosympathisch zenuwstelsel neemt af
B orthosympathisch zenuwstelsel neemt toe
C parasympathisch zenuwstelsel neemt af
D parasympathisch zenuwstelsel neemt toe$$, array['11d24dd6-2f3a-455a-915e-c14ba9aab88a']::uuid[]),
  ('6f772356-f245-4a03-9cdf-33c6b09d37f3', 'd957557f-9111-4a34-a56f-210a7d6e6bfe', 4,
   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["bloeddruk", "slagvolume", "hartcyclus", "bloedvaten"]'::jsonb,
   $$Verklaren dat een groter slagvolume meer bloed per slag in de slagaders brengt, waardoor de bloeddruk stijgt.$$,
